import {useEffect,useState} from "react"
import {getProducts} from "../services/catalogApi"

export default function Home(){

 const [products,setProducts]=useState([])

 useEffect(()=>{
  getProducts().then(setProducts)
 },[])

 return (
   <>
    <Header/>
    <CategoryBar/>
    <ProductGrid products={products}/>
   </>
 )
}
